@Override public AudioOffloadSupport getAudioOffloadSupport(Format format,AudioAttributes audioAttributes){
  checkNotNull(format);
  checkNotNull(audioAttributes);
  if (Util.SDK_INT < 29 || format.sampleRate == Format.NO_VALUE) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  boolean isOffloadVariableRateSupported=isOffloadVariableRateSupported(context);
  @C.Encoding int encoding=MimeTypes.getEncoding(checkNotNull(format.sampleMimeType),format.codecs);
  if (encoding == C.ENCODING_INVALID) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  if ((Util.SDK_INT < 34) && (encoding == C.ENCODING_DTS_UHD_P2)) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  int channelConfig=Util.getAudioTrackChannelConfig(format.channelCount);
  if (channelConfig == AudioFormat.CHANNEL_INVALID) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  AudioFormat audioFormat=Util.getAudioFormat(format.sampleRate,channelConfig,encoding);
  AudioOffloadSupport support;
  try {
    if (Util.SDK_INT >= 31) {
      support = Api31.getOffloadedPlaybackSupport(audioFormat,audioAttributes.getAudioAttributesV21().audioAttributes,isOffloadVariableRateSupported);
    } else {
      support = Api29.getOffloadedPlaybackSupport(audioFormat,audioAttributes.getAudioAttributesV21().audioAttributes,isOffloadVariableRateSupported);
    }
  } catch (IllegalStateException e) {
    // Handle the exception, e.g., log it or return a default value
    support = AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  return support;
}
